      }
    ]
  },
  "enrollment": 150,
  "interventions": [
    {
      "description": "EIM is an impedance-based technology in which an imperceptible, high-, multi-frequency (e.g., 1 kHz to 10 MHz) electrical current is applied across two electrodes; the resulting voltage signals are measured across two sense electrodes",
      "id": 1,
      "name": "Electrical Impedance Myography",
      "other_names": [],
      "type": {
        "authority": "clinicaltrials.gov",
        "code": "DEVICE",
        "display": null,
