  "eligibility": {
    "age_range": null,
    "criteria": null,
    "includes_healthy_subjects": false,
    "registry_text": "Inclusion Criteria:\n\n* patients with rare genetic muscle diseases who have benefited from high-throughput sequencing analysis (panel of 200 genes defined by the FILNEMUS Rare Neuromuscular Disease Network) carried out at the Molecular Genetics Laboratory, Medical Genetics Department, Timone Enfant Hospital since 2017.\n\nThis criterion is necessary to limit the analysis to patients with muscular diseases among all the patients analysed by the Molecular Genetics Laboratory.\n\n* this genetic analysis did not identify pathogenic variants explaining the patient's phenotype This criterion is necessary in order to include only patients in diagnostic error.\n* a muscle biopsy of the patient is available in the Biological Resources Centre (CRB) at the AP-HM.\n\nExclusion Criteria:\n\n* Patients with no muscle biopsy available in the CRB.\n* Patients with an established molecular diagnosis.\n* Patients for whom RNA extraction from a muscle biopsy sample did not yield RNA of sufficient quality (INR \\>7) will be excluded from the study. A maximum of two extraction attempts will be performed.",
    "sexes": [
      {
        "authority": "clinicaltrials.gov",
        "code": "ALL",
        "display": null,
        "recognized_meaning": null,
        "vocabulary_version": null
      }
    ]
  },
  "enrollment": 50,
  "interventions": [
    {
      "description": "There will be no visits from participants, so we will be using samples already in the Biological Resources Centre (CRB).\n\nRNA will be extracted from muscle biopsies taken as part of the treatment. RNAseq libraries will be sequenced by the Genomics and Bioinformatics Platform (GBiM) at Marseille Medical Genetics (MMG, U1251, AMU). Sequencing will be performed in paired-end (2\\*100 bp) on Illumina's Novaseq 6000 system (50 million clusters per sample, 100 M paired-end reads) and then analysed by bioinformatics.",
      "id": 1,
      "name": "ARN extraction from muscle biopsies",
      "other_names": [],
      "type": {
        "authority": "clinicaltrials.gov",
        "code": "OTHER",
        "display": null,
        "recognized_meaning": null,
        "vocabulary_version": null
      }
    }
  ],
  "nct_id": "NCT06833489",
  "phase": "NA",
  "source": "ClinicalTrials.gov",
  "sponsor": "Assistance Publique Hopitaux De Marseille",
  "start_date": "2025-01-23",
  "status": "RECRUITING",
  "study_type": "INTERVENTIONAL",
  "summary": "Since 2017, more than 250 analyses performed at the Molecular Genetics Laboratory of the Timone Enfant Hospital have yielded negative results in patients with rare genetic muscle diseases. The researchers hypothesise that some of these misdiagnosed patients carry pathogenic RNA (transcript) disrupting variants that were not identified by DNA sequencing. In fact, DNA sequencing analyses can be negative despite the presence of a pathogenic variant that disrupts RNA splicing or expression, causing a genetic disease. For this reason, RNA sequencing can provide a diagnosis in patients who have not been diagnosed by DNA sequencing, thus putting an end to diagnostic wandering. Thus, as a descriptive prevalence study, the objectives are first to determine the rate of positive diagnoses made by the RNAseq approach in patients with muscle diseases that have not yet been diagnosed, and then to identify the genomic characteristics of the pathogenic variants identified in patients by RNAseq analysis, in order to facilitate the identification of this type of variant in future patients.\n\n50 patients will be included in this study during 2 years.",
  "title": "Transcriptomic Analysis to Put an End to Misdiagnosis in Patients With Rare Muscle Diseases"
}

